// The Node half of `mt-highlight`'s grammar generator (docs/M3.md §5 D14).
//
//   prismjs (reference clone) ──► this script ──► grammars.json
//                                                      │
//                          xtask/src/grammars.rs ◄──────┘
//                                    │
//                    crates/mt-highlight/src/generated.rs   (committed)
//
// WHY A SNAPSHOT AND NOT A TRANSCRIPTION
//
// D14 in one sentence: *"`mt-highlight`'s grammar tables are generated by
// loading Prism in Node, walking `Prism.languages`, and emitting Rust data."*
// The decision exists because D3's load-bearing claim — *"Prism grammars are
// data"* — is **false of the source**. 91 of the 297 grammar files build
// regexes at load time with `RegExp(…)` or `.source` surgery, and 130 call
// `extend`/`insertBefore`, so a third of the corpus is a program.
//
// What rescues it is that all of that runs at **load** time. After requiring
// all 297, the reachable registry contains **zero** function-valued leaves —
// the only three functions on `Prism.languages` are its own API (`extend`,
// `insertBefore`, `DFS`), which are skipped here by name and asserted to be the
// only ones. So the port copies the *output* of Prism's load rather than its
// input, and this script is that copy.
//
// WHY THE NODE HALF ONLY DUMPS
//
// It writes JSON and translates nothing. Every JS-regex → Rust-regex decision
// lives in `xtask/src/grammars.rs`, in Rust, where it can be **checked by
// compiling the result with the same `fancy-regex` the interpreter will use**.
// A translator written here could only check its output by eye. The split is
// the same one `tools/diff/` uses: Node reaches the reference, Rust decides.
//
// THE LOAD SET IS PART OF THE CONTRACT (D14 consequence 2)
//
// The full 297, in `components/index.js`'s dependency order, exactly as
// `tools/diff/dump-prism-tokens.mjs` loads them — and for the same reason: 13
// grammar files mutate *other* grammars at load time (`java` is its own
// definition until `javadoc` loads and 208 entries afterwards), so a grammar's
// content is a property of the load set. Both sides of S3's differential load
// the same set or the differential is measuring its own configuration.
//
// muya's two patches are applied here too, and for the third time in this
// repository, because the question is *"does the port match MarkText"*: `c++`
// and `h++` become aliases of `cpp`, and `latex.comment` gains the lookbehind
// that stops `\%` from commenting out the rest of the line. See
// `dump-prism-tokens.mjs`'s header for the references.
//
// THREE THINGS THE WALK HAS TO GET RIGHT
//
//  1. **`inside` is a graph, not a tree.** Grammar objects are shared by
//     reference and the reference graph has cycles — `markup`'s `script` tag
//     contains `javascript`, whose template strings contain `markup`. So this
//     dumps an **interned node table**: every distinct grammar *object* gets an
//     index, and `inside` is an index. 403 names in `Prism.languages` reach
//     1,628 distinct grammar objects.
//
//  2. **`rest` is merged here, once.** `Prism.tokenize` merges `grammar.rest`
//     into the grammar and deletes it (prism-core.js:894-901) — a destructive
//     mutation of a shared object, so it happens at most once per object no
//     matter how many times tokenize runs. Doing it eagerly is therefore not an
//     optimisation but the only way to snapshot what the interpreter would see;
//     98 reachable grammars carry one. JS assignment semantics are reproduced
//     exactly: a key that already exists keeps its **position** in the key order
//     and takes the new value, a key that does not is appended.
//
//  3. **Key order is the evaluation order.** `matchGrammar` is
//     `for (var token in grammar)`, so the order rules are tried in is the
//     object's own insertion order, and it decides which of two overlapping
//     patterns wins. `Object.keys` preserves it — except for integer-like keys,
//     which JS hoists to the front in numeric order. No grammar has one; this
//     script asserts that rather than trusting it.
//
// USAGE
//   node tools/dump-prism-grammars.mjs --out <FILE> [--marktext <DIR>]
//
// OUTPUT
//   { engine, prism: {version, languages, grammars, modifierPacks},
//     patches: [str…], manifest: [id…], aliases: {alias: id},
//     languages: {name: grammarIndex}, grammars: [ [ {name, patterns} … ] … ] }
//
//   `patterns[i]` is `{source, flags, lookbehind, greedy, alias, inside}` where
//   `source` is `RegExp.prototype.source` verbatim — untranslated, because
//   translating is the Rust half's job — `alias` is the **single resolved
//   class** D15 fixes (*alias over type, last alias wins*) or `null`, and
//   `inside` is an index into `grammars` or `null`.
//
// EXIT CODES
//   0 success · 1 error · 3 Prism could not be loaded (same convention, and the
//   same reason, as the three dumpers under `tools/diff/`).

import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const EXIT_OK = 0;
const EXIT_ERROR = 1;
const EXIT_ENGINE_UNAVAILABLE = 3;

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

class EngineUnavailable extends Error {}

function parseArgs(argv) {
    let outFile = null;
    let marktextDir = null;
    for (let i = 0; i < argv.length; i++) {
        const arg = argv[i];
        if (arg === '--out') {
            outFile = argv[++i];
            if (outFile === undefined)
                throw new Error('--out requires a file argument');
        }
        else if (arg === '--marktext') {
            marktextDir = argv[++i];
            if (marktextDir === undefined)
                throw new Error('--marktext requires a directory argument');
        }
        else if (arg === '--help' || arg === '-h') {
            return { help: true };
        }
        else {
            throw new Error(`unrecognised argument: ${arg}`);
        }
    }
    return { outFile, marktextDir, help: false };
}

/**
 * Locate the marktext clone — identical policy to `tools/diff/`'s three
 * dumpers, down to the sentinel file, so that one `$MARKTEXT_DIR` configures
 * every script in this repository that reaches for the reference.
 */
function resolveMarktextDir(explicit) {
    const named = explicit ?? process.env.MARKTEXT_DIR;
    const source = explicit ? '--marktext' : '$MARKTEXT_DIR';
    const candidates = named ? [named] : [path.resolve(repoRoot, '..', 'marktext')];
    for (const candidate of candidates) {
        const aliasTable = path.join(
            candidate, 'packages', 'muya', 'src', 'utils', 'prism', 'loadLanguage.ts',
        );
        if (fs.existsSync(aliasTable))
            return path.resolve(candidate);
    }
    throw new EngineUnavailable(
        named
            ? `${source} points at ${named}, which does not contain `
              + 'packages/muya/src/utils/prism/loadLanguage.ts.'
            : `could not find the marktext clone at ${candidates[0]}.\n`
              + 'Set MARKTEXT_DIR or pass --marktext <DIR>.',
    );
}

/** Load Prism and all 297 grammars. Mirrors `dump-prism-tokens.mjs:322-394`. */
function loadPrism(marktextDir) {
    const require = createRequire(path.join(marktextDir, 'package.json'));
    let Prism;
    let components;
    let loadLanguages;
    let version;
    try {
        Prism = require('prismjs');
        components = require('prismjs/components.js');
        loadLanguages = require('prismjs/components/index.js');
        version = require('prismjs/package.json').version;
    }
    catch (cause) {
        throw new EngineUnavailable(
            `failed to load prismjs from ${marktextDir}: ${cause.message}\n`
            + 'Run:  pnpm install --filter @muyajs/core --ignore-scripts\n'
            + `in ${marktextDir}`,
        );
    }

    const patches = applyMuyaAliasPatch(components);
    const ids = Object.keys(components.languages).filter(id => id !== 'meta');
    loadLanguages.silent = true;
    try {
        loadLanguages(ids);
    }
    catch (cause) {
        throw new EngineUnavailable(
            `prismjs failed to load its ${ids.length} grammars: ${cause.message}`,
        );
    }
    patches.push(...applyMuyaLatexPatch(Prism));

    const modifierPacks = ids.filter(
        id => !Object.prototype.hasOwnProperty.call(Prism.languages, id),
    );
    return { Prism, components, ids, version, modifierPacks, patches };
}

/** muya's `c++`/`h++` aliases — `utils/prism/index.ts:16-24`. */
function applyMuyaAliasPatch(components) {
    const cpp = components.languages.cpp;
    if (!cpp)
        return [];
    const existing = cpp.alias;
    const alias = Array.isArray(existing) ? [...existing] : existing ? [existing] : [];
    const added = [];
    for (const name of ['c++', 'h++']) {
        if (!alias.includes(name)) {
            alias.push(name);
            added.push(name);
        }
    }
    cpp.alias = alias;
    return added.length ? [`cpp: +${added.join(' +')} (marktext utils/prism/index.ts:16-24)`] : [];
}

/** muya's LaTeX escaped-percent fix — `utils/prism/index.ts:74-78`. */
function applyMuyaLatexPatch(Prism) {
    const latex = Prism.languages.latex;
    if (!latex?.comment)
        return [];
    latex.comment = { pattern: /(^|[^\\])%.*/, lookbehind: true };
    return ['latex.comment: /(^|[^\\\\])%.*/ lookbehind (marktext utils/prism/index.ts:74-78)'];
}

// ---------------------------------------------------------------------------
// The walk
// ---------------------------------------------------------------------------

/**
 * The three functions that live on `Prism.languages` itself.
 *
 * They are the registry's own API, not grammars, and they are the *only*
 * function-valued leaves D14 measured in the whole reachable graph. Named here
 * rather than filtered by `typeof`, so that a fourth one appearing after a
 * prismjs bump is a hard failure instead of a silent omission.
 */
const REGISTRY_API = new Set(['extend', 'insertBefore', 'DFS']);

/** The keys a `GrammarToken` object may carry — prism-core.js:1218-1232. */
const TOKEN_KEYS = new Set(['pattern', 'lookbehind', 'greedy', 'alias', 'inside']);

/**
 * `rest`, merged exactly as `Prism.tokenize` merges it (prism-core.js:894-901).
 *
 * Done eagerly and to a fixpoint over the whole reachable graph, because the
 * real merge is a destructive mutation of a shared object: whichever tokenize
 * call happens first performs it and every later one sees the merged form, so
 * "before any tokenize" and "after all of them" are the same snapshot. Doing it
 * here rather than in the interpreter also keeps `rest` out of the Rust data
 * entirely, which means the interpreter has one fewer branch that could differ.
 */
function mergeRest(grammar) {
    const rest = grammar.rest;
    if (!rest)
        return;
    for (const token in rest)
        grammar[token] = rest[token];
    delete grammar.rest;
}

function main() {
    let args;
    try {
        args = parseArgs(process.argv.slice(2));
    }
    catch (e) {
        process.stderr.write(`dump-prism-grammars: ${e.message}\n`);
        return EXIT_ERROR;
    }
    if (args.help) {
        process.stdout.write(fs.readFileSync(fileURLToPath(import.meta.url), 'utf8')
            .split('\n')
            .filter(l => l.startsWith('//'))
            .map(l => l.replace(/^\/\/ ?/, ''))
            .join('\n') + '\n');
        return EXIT_OK;
    }

    let engine;
    let marktextDir;
    try {
        marktextDir = resolveMarktextDir(args.marktextDir);
        engine = loadPrism(marktextDir);
    }
    catch (e) {
        if (e instanceof EngineUnavailable) {
            process.stderr.write(`dump-prism-grammars: engine unavailable: ${e.message}\n`);
            return EXIT_ENGINE_UNAVAILABLE;
        }
        throw e;
    }

    const { Prism, components, ids } = engine;
    const interned = new Map();
    const grammars = [];

    /** Intern one grammar object, returning its index. `where` is for errors. */
    function intern(grammar, where) {
        const already = interned.get(grammar);
        if (already !== undefined)
            return already;
        const index = grammars.length;
        interned.set(grammar, index);
        const rules = [];
        // Pushed *before* the walk, so a cycle that comes back to this object
        // finds the index rather than recursing forever. The array is filled in
        // afterwards; nothing reads a neighbour's rules during the walk.
        grammars.push(rules);

        mergeRest(grammar);

        const keys = Object.keys(grammar);
        for (const key of keys) {
            if (/^(?:0|[1-9][0-9]*)$/.test(key)) {
                // JS hoists integer-like own keys to the front of the iteration
                // order regardless of insertion order, so a grammar with one
                // would be tried in an order this dump cannot express. None
                // exists; this is the assertion, not a repair.
                throw new Error(`${where}.${key}: integer-like grammar key`);
            }
            const value = grammar[key];
            // `matchGrammar` skips falsy entries outright (prism-core.js:917).
            if (!value)
                continue;
            const list = Array.isArray(value) ? value : [value];
            const patterns = [];
            for (let j = 0; j < list.length; j++) {
                patterns.push(pattern(list[j], `${where}.${key}[${j}]`, key));
            }
            rules.push({ name: key, patterns });
        }
        return index;
    }

    /** One `GrammarToken` — or a bare `RegExp`, which Prism also accepts. */
    function pattern(entry, where, ruleName) {
        let regex = entry;
        let lookbehind = false;
        let greedy = false;
        let alias = null;
        let inside = null;

        if (!(entry instanceof RegExp)) {
            if (entry === null || typeof entry !== 'object')
                throw new Error(`${where}: grammar entry is ${typeof entry}, not a pattern`);
            for (const key of Object.keys(entry)) {
                if (!TOKEN_KEYS.has(key))
                    throw new Error(`${where}.${key}: unknown GrammarToken key`);
            }
            regex = entry.pattern;
            lookbehind = !!entry.lookbehind;
            greedy = !!entry.greedy;
            alias = resolveClass(entry, ruleName);
            if (entry.inside) {
                if (typeof entry.inside !== 'object')
                    throw new Error(`${where}.inside: ${typeof entry.inside}, not a grammar`);
                inside = intern(entry.inside, `${where}.inside`);
            }
        }
        if (!(regex instanceof RegExp))
            throw new Error(`${where}.pattern: ${typeof regex}, not a RegExp`);
        return {
            source: regex.source,
            flags: regex.flags,
            lookbehind,
            greedy,
            alias: alias === ruleName ? null : alias,
            inside,
        };
    }

    /**
     * The single class a token paints in: **alias over type, last alias wins**.
     *
     * D15's recorded precedence, and `dump-prism-tokens.mjs:524-531`'s
     * `resolveClass` verbatim — the two must agree or the differential compares
     * a class the reference never emits. Prism writes
     * `class="token <type> <alias>…"` and muya's stylesheet resolves by source
     * order, so the last alias is the one a browser paints.
     */
    function resolveClass(entry, ruleName) {
        const alias = entry.alias;
        if (Array.isArray(alias))
            return alias.length ? alias[alias.length - 1] : ruleName;
        if (typeof alias === 'string' && alias !== '')
            return alias;
        return ruleName;
    }

    // Roots. Every name in `Prism.languages`, including the aliases Prism
    // registers as shared references (`html`, `xml` and `svg` are `markup`'s
    // very object) — the sharing is a property of the registry that the port
    // has to reproduce, and interning by identity reproduces it for free.
    const languages = {};
    for (const name of Object.keys(Prism.languages)) {
        const value = Prism.languages[name];
        if (typeof value === 'function') {
            if (!REGISTRY_API.has(name))
                throw new Error(`Prism.languages.${name} is a function and is not the registry API`);
            continue;
        }
        if (typeof value !== 'object' || value === null)
            throw new Error(`Prism.languages.${name} is ${typeof value}`);
        languages[name] = intern(value, name);
    }

    // MarkText's `transformAliasToOrigin` (`utils/prism/loadLanguage.ts:23-54`)
    // as a table rather than as a search: a manifest id is itself, otherwise the
    // **first** language claiming the word as an alias in `components.json` key
    // order wins. Only the second case needs a table; the port checks manifest
    // membership first, exactly as the reference's first branch does.
    const aliases = {};
    for (const id of Object.keys(components.languages)) {
        if (id === 'meta')
            continue;
        const alias = components.languages[id].alias;
        if (!alias)
            continue;
        for (const name of Array.isArray(alias) ? alias : [alias]) {
            if (Object.prototype.hasOwnProperty.call(components.languages, name))
                continue; // a real id shadows any alias of the same word
            if (!Object.prototype.hasOwnProperty.call(aliases, name))
                aliases[name] = id; // first claimant wins
        }
    }

    const envelope = {
        engine: `prismjs ${engine.version} (components/index.js, full load)`,
        prism: {
            version: engine.version,
            languages: ids.length,
            grammars: ids.length - engine.modifierPacks.length,
            modifierPacks: engine.modifierPacks,
        },
        patches: engine.patches,
        manifest: ids,
        aliases,
        languages,
        grammars,
    };
    // Pretty-printed with two spaces. This file is an intermediate under
    // `target/` and is never committed, but a generator whose input cannot be
    // read by eye is a generator whose disagreements cannot be investigated.
    const text = `${JSON.stringify(envelope, null, 2)}\n`;
    if (args.outFile)
        fs.writeFileSync(args.outFile, text);
    else
        process.stdout.write(text);
    return EXIT_OK;
}

process.exitCode = main();
